package com.example.platform.studio.shotscene;
import com.example.platform.studio.camera.Transform;import com.example.platform.studio.identity.*;import com.example.platform.studio.reference.StudioVersionPin;import com.example.platform.studio.serialization.CanonicalJson;import java.util.*;
public record SceneElement(SceneElementId id,Kind kind,SceneElementId parentId,Transform localTransform,List<SceneElementId>references,StudioVersionPin<CameraPlanId,CameraPlanVersionId>cameraPlanPin,String semanticRole){
public enum Kind{CHARACTER,PROP,ENVIRONMENT,LIGHT_INTENT,CAMERA_REFERENCE,MARKER}
public SceneElement(SceneElementId id,Kind kind,SceneElementId parentId,Transform localTransform,List<SceneElementId>references,String semanticRole){this(id,kind,parentId,localTransform,references,null,semanticRole);}
public SceneElement{if(id==null||kind==null||localTransform==null||references==null)throw new IllegalArgumentException("scene element fields required");if((kind==Kind.CAMERA_REFERENCE)!=(cameraPlanPin!=null))throw new IllegalArgumentException("camera reference requires exactly one CameraPlan pin");semanticRole=CanonicalJson.requiredText(semanticRole,"semantic role");if(semanticRole.length()>300||semanticRole.matches("(?is).*(exec|script|command|--|://).*"))throw new IllegalArgumentException("semantic role violates safe contract");references=List.copyOf(references);if(references.stream().anyMatch(Objects::isNull)||new HashSet<>(references).size()!=references.size())throw new IllegalArgumentException("invalid duplicate local references");}
public String canonicalJson(){Map<String,String>m=new LinkedHashMap<>();if(cameraPlanPin!=null)m.put("cameraPlanPin",cameraPlanPin.canonicalJson());m.put("id",CanonicalJson.quote(id.value()));m.put("kind",CanonicalJson.quote(kind.name()));m.put("localTransform",localTransform.canonicalJson());if(parentId!=null)m.put("parentId",CanonicalJson.quote(parentId.value()));m.put("references",CanonicalJson.array(references.stream().map(r->CanonicalJson.quote(r.value())).toList()));m.put("semanticRole",CanonicalJson.quote(semanticRole));return CanonicalJson.object(m);}}
